use gocompat::utf8::{self, Rune};

use super::composition::{HANGUL_BASE, HANGUL_END};
use super::normalize::Form;

const YES: u8 = 0;
const NO: u8 = 1;
const MAYBE: u8 = 2;

#[derive(Clone, Copy)]
struct FormData {
    qc: u8,
    combines_forward: bool,
    decomposition: &'static str,
}

#[derive(Clone, Copy)]
struct RuneData {
    r: Rune,
    ccc: u8,
    n_lead: u8,
    n_trail: u8,
    f: [FormData; 2],
}

const fn f(qc: u8, cf: bool, dec: &'static str) -> [FormData; 2] {
    let d = FormData {
        qc,
        combines_forward: cf,
        decomposition: dec,
    };
    [d, d]
}

const fn g(
    qc: u8,
    qck: u8,
    cf: bool,
    cfk: bool,
    d: &'static str,
    dk: &'static str,
) -> [FormData; 2] {
    [
        FormData {
            qc,
            combines_forward: cf,
            decomposition: d,
        },
        FormData {
            qc: qck,
            combines_forward: cfk,
            decomposition: dk,
        },
    ]
}

const fn rd(r: Rune, ccc: u8, n_lead: u8, n_trail: u8, f: [FormData; 2]) -> RuneData {
    RuneData {
        r,
        ccc,
        n_lead,
        n_trail,
        f,
    }
}

#[test]
fn test_properties() {
    let ck = ["C", "K"];
    let mut d = TEST_DATA[0];
    let mut k = 1;
    for r in 0..0x2ffff {
        if k < TEST_DATA.len() && r == TEST_DATA[k].r {
            d = TEST_DATA[k];
            k += 1;
        }
        let mut s = Vec::new();
        utf8::append_rune(
            &mut s,
            if utf8::valid_rune(r) {
                r
            } else {
                utf8::RUNE_ERROR
            },
        );
        let props = [
            Form::Nfc.properties_string(&s),
            Form::Nfkc.properties_string(&s),
        ];
        for (j, p) in props.iter().enumerate() {
            let f = d.f[j];
            assert_eq!(p.ccc(), d.ccc, "U+{r:04X}: ccc({})", ck[j]);
            assert_eq!(p.is_yes_c(), f.qc == YES, "U+{r:04X}: YesC({})", ck[j]);
            assert_eq!(
                p.combines_backward(),
                f.qc == MAYBE,
                "U+{r:04X}: combines backwards({})",
                ck[j]
            );
            assert_eq!(
                p.n_leading_non_starters(),
                d.n_lead,
                "U+{r:04X}: nLead({})",
                ck[j]
            );
            assert_eq!(
                p.n_trailing_non_starters(),
                d.n_trail,
                "U+{r:04X}: nTrail({})",
                ck[j]
            );
            assert_eq!(
                p.combines_forward(),
                f.combines_forward,
                "U+{r:04X}: combines forward({})",
                ck[j]
            );
            if (HANGUL_BASE..HANGUL_END).contains(&r) {
                continue;
            }
            if p.has_decomposition() {
                assert!(
                    !f.decomposition.is_empty(),
                    "U+{r:04X}: hasDecomposition({})",
                    ck[j]
                );
                assert_eq!(
                    p.decomposition().unwrap_or(&[]),
                    f.decomposition.as_bytes(),
                    "U+{r:04X}: decomp({})",
                    ck[j]
                );
            }
        }
    }
}

